const NL = String.fromCharCode(10);
const robotsItem = $input.first().json;
const robots = typeof robotsItem.data === "string" ? robotsItem.data : "";
const PAGES = [
  { key: "price-list", label: "ITC price list", page_type: "price_list", url: "https://www.placidway.com/price-list/5/Alternative-Cancer-Treatment-by-ITC-Immunity-Therapy-Center" },
  { key: "profile", label: "ITC profile", page_type: "profile", url: "https://www.placidway.com/profile/5/Alternative-Cancer-Treatment-by-ITC-Immunity-Therapy-Center" },
  { key: "pkg-adenocarcinoma", label: "Adenocarcinoma package", page_type: "package", url: "https://www.placidway.com/package/7903/Alternative-Adenocarcinoma-Cancer-Treatment-Package-in-Tijuana-Mexico-by-ITC" },
  { key: "pkg-adrenal", label: "Adrenal package", page_type: "package", url: "https://www.placidway.com/package/7902/Alternative-Adrenal-Cancer-Treatment-Package-in-Tijuana-Mexico-by-ITC" },
  { key: "pkg-anal", label: "Anal package", page_type: "package", url: "https://www.placidway.com/package/7901/Alternative-Anal-Cancer-Treatment-Package-in-Tijuana-Mexico-by-ITC" },
  { key: "videos", label: "ITC videos", page_type: "videos", url: "https://www.placidway.com/profile-videos/5/Alternative-Cancer-Treatment-by-ITC-Immunity-Therapy-Center" },
  { key: "comparison", label: "Comparison page", page_type: "comparison", url: "https://www.placidway.com/search-medical-pricings/Alternative-Medicine/All/1" }
];
let applies = false;
const disallow = [];
const allow = [];
robots.split(NL).forEach(function (ln) {
  const s = ln.split("#")[0].trim();
  const i = s.indexOf(":");
  if (i < 0) return;
  const k = s.slice(0, i).trim().toLowerCase();
  const v = s.slice(i + 1).trim();
  if (k === "user-agent") applies = v === "*";
  else if (applies && k === "disallow" && v) disallow.push(v);
  else if (applies && k === "allow" && v) allow.push(v);
});
function longest(rules, path) {
  let best = -1;
  rules.forEach(function (r) { if (path.indexOf(r) === 0 && r.length > best) best = r.length; });
  return best;
}
const allowed = [];
const blocked = [];
PAGES.forEach(function (p) {
  const path = p.url.slice(p.url.indexOf("/", 8));
  if (longest(disallow, path) > longest(allow, path)) blocked.push(p.key);
  else allowed.push(p);
});
if (!allowed.length) throw new Error("robots.txt disallows all source pages; refresh aborted.");
const robotsStatus = robots ? "checked" : "unavailable (treated as allowed)";
return allowed.map(function (p) { return { json: Object.assign({}, p, { blockedPages: blocked, robotsStatus: robotsStatus }) }; });

const NL = String.fromCharCode(10);
const WS = "[ " + String.fromCharCode(9, 10, 13, 160) + "]+";
const ARROW = " " + String.fromCharCode(8250) + " ";
function rx(p, f) { return new RegExp(p, f); }
function squash(s) { return s.replace(rx(WS, "g"), " ").trim(); }
const pages = $("Page List and Robots Check").all().map(function (i) { return i.json; });
const fetched = $input.all().map(function (i) { return i.json; });
const scrapedAt = new Date().toISOString().slice(0, 10);

const ENT = [["&nbsp;", " "], ["&amp;", "&"], ["&quot;", '"'], ["&#39;", "'"], ["&#x27;", "'"], ["&apos;", "'"], ["&lt;", "<"], ["&gt;", ">"], ["&rsquo;", "'"], ["&lsquo;", "'"], ["&rdquo;", '"'], ["&ldquo;", '"'], ["&ndash;", "-"], ["&mdash;", "-"], ["&hellip;", "..."]];
function decode(s) { ENT.forEach(function (e) { s = s.split(e[0]).join(e[1]); }); return s; }
function stripTags(s) { return s.replace(rx("<[^>]+>", "g"), " "); }

function toLines(html) {
  ["script", "style", "noscript", "svg", "iframe", "template", "select", "button", "nav", "footer"].forEach(function (t) {
    html = html.replace(rx("<" + t + "[^>]*>[^]*?</" + t + ">", "gi"), " ");
  });
  html = html.replace(rx("<!--[^]*?-->", "g"), " ");
  html = html.replace(rx("<tr[^>]*>([^]*?)</tr>", "gi"), function (m, inner) {
    const cells = [];
    inner.replace(rx("<t[dh][^>]*>([^]*?)</t[dh]>", "gi"), function (mm, c) { cells.push(squash(decode(stripTags(c)))); return ""; });
    return "<p>" + cells.filter(Boolean).join(" | ") + "</p>";
  });
  for (let n = 1; n <= 6; n++) {
    html = html.replace(rx("<h" + n + "[^>]*>([^]*?)</h" + n + ">", "gi"), function (m, c) {
      return NL + NL + "#".repeat(n) + " " + squash(decode(stripTags(c))) + NL;
    });
  }
  html = html.replace(rx("<li[^>]*>", "gi"), NL + "- ");
  html = html.replace(rx("</(p|div|section|ul|ol|li|article|tr|table|dd|dt)>", "gi"), NL);
  html = html.replace(rx("<br[^>]*>", "gi"), NL);
  html = decode(stripTags(html));
  return html.split(NL).map(squash).filter(function (l) { return l.length > 0; });
}
function headingLevel(l) {
  let n = 0;
  while (l[n] === "#") n++;
  return n > 0 && n <= 6 && l[n] === " " ? n : 0;
}
const EXCLUDE = ["review", "testimonial", "patient stor", "related", "explore", "you may also", "similar", "top medical center", "top package", "unlock the best", "transformative", "trending", "article", "podcast", "frequently searched", "top procedures", "request your free quote", "download", "confirm your virtual", "request a video call", "real families", "families say"];
const TRUNCATE = ["accreditations", "about placidway", "follow us", "newsletter", "subscribe", "our network"];
function matches(list, text) {
  const t = text.toLowerCase();
  return list.some(function (k) { return t.indexOf(k) > -1; });
}
function commas(d) {
  let o = "";
  for (let i = 0; i < d.length; i++) { if (i > 0 && (d.length - i) % 3 === 0) o += ","; o += d[i]; }
  return o;
}
function normPrices(s) {
  s = s.replace(rx("[$] ?([0-9]{4,})", "g"), function (m, d) { return "$" + commas(d); });
  s = s.replace(rx("([0-9]{4,}) ?USD", "g"), function (m, d) { return "USD $" + commas(d); });
  return s;
}
function words(s) { return s.split(" ").filter(Boolean).length; }
function slug(s) {
  let o = "";
  const l = s.toLowerCase();
  for (let i = 0; i < l.length && o.length < 40; i++) {
    const c = l[i];
    o += (c >= "a" && c <= "z") || (c >= "0" && c <= "9") ? c : "-";
  }
  return o.split("-").filter(Boolean).join("-");
}
function splitBody(lines) {
  const parts = [];
  let cur = [];
  let w = 0;
  lines.forEach(function (l) {
    const lw = words(l);
    if (w + lw > 250 && cur.length) { parts.push(cur.join(NL)); cur = []; w = 0; }
    cur.push(l);
    w += lw;
  });
  if (cur.length) parts.push(cur.join(NL));
  return parts;
}
function hash(s) {
  let h = 2166136261;
  for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 16777619) >>> 0; }
  return h.toString(16);
}
const OUTCOME = ["worked", "miracle", "remission", "survivor", "survive", "survival", "beat", "beating", "cured", "cancer-free", "cancer free", "no evidence", "success", "overcame", "journey", "recovered", "healed", "patient says", "patient story", "real patient", "reviews"];
const VIDEO_STOP = ["i agree to the terms", "take a look at these", "price starting from", "accreditations", "we collaborate with", "a real patient story"];
const VIDEO_DENY = ["publish date", "modified date", "medically reviewed", "read more", "share your", "request a consultation", "contact itc", "about itc", "founded by"];

const chunks = [];
const report = [];
const usedIds = {};
function pushChunk(p, pageTitle, section, type, bodyText, tag) {
  let id = p.key + "--" + (tag || slug(section) || "section");
  if (usedIds[id]) { usedIds[id] += 1; id = id + "-" + usedIds[id]; } else usedIds[id] = 1;
  chunks.push({ id: id, url: p.url, title: pageTitle, page_type: p.page_type, section: section, chunk_type: type, text: "[" + p.label + ARROW + section + "] " + bodyText });
}

pages.forEach(function (p, idx) {
  const f = fetched[idx] || {};
  const html = typeof f.data === "string" ? f.data : "";
  const tm = html.match(rx("<title[^>]*>([^<]*)</title>", "i"));
  const pageTitle = tm ? squash(decode(tm[1])) : p.label;
  const before = chunks.length;
  let status = "ok";
  let reason = "";
  let pageText = "";
  if (html.length < 3000) {
    status = "failed";
    reason = "empty or blocked response";
  } else {
    const lines = toLines(html);
    const start = lines.findIndex(function (l) { return l.indexOf("# ") === 0; });
    if (start < 0) {
      status = "failed";
      reason = "no main heading found";
    } else if (p.key === "videos") {
      let end = lines.length;
      for (let i = start + 1; i < lines.length; i++) {
        if (matches(VIDEO_STOP, lines[i])) { end = i; break; }
      }
      const seen = {};
      const titles = [];
      lines.slice(start + 1, end).forEach(function (l) {
        let t = l;
        while (t[0] === "#" || t[0] === "-" || t[0] === " ") t = t.slice(1);
        if (t.length < 25 || t.length > 220 || seen[t]) return;
        if (matches(OUTCOME, t) || matches(VIDEO_DENY, t)) return;
        seen[t] = true;
        titles.push(t);
      });
      for (let i = 0; i < titles.length; i += 12) {
        const grp = titles.slice(i, i + 12);
        pushChunk(p, pageTitle, "Video titles " + (Math.floor(i / 12) + 1), "video_titles", "Titles only (the page gives no descriptions or transcripts): " + grp.join("; "), "video-titles-" + (Math.floor(i / 12) + 1));
        pageText += grp.join(" ");
      }
      if (!titles.length) { status = "failed"; reason = "no video titles found"; }
    } else {
      const sections = [];
      let cur = { heading: "Overview", body: [] };
      let skipLevel = 0;
      for (let i = start + 1; i < lines.length; i++) {
        const l = lines[i];
        const lv = headingLevel(l);
        if (lv > 0) {
          const text = l.slice(lv + 1);
          if (matches(TRUNCATE, text)) break;
          if (skipLevel > 0 && lv > skipLevel) continue;
          skipLevel = 0;
          if (cur && cur.body.length) sections.push(cur);
          if (matches(EXCLUDE, text)) { skipLevel = lv; cur = null; } else cur = { heading: text, body: [] };
        } else if (cur && skipLevel === 0) {
          cur.body.push(l);
        }
      }
      if (cur && cur.body.length) sections.push(cur);
      sections.forEach(function (sec) {
        const body = sec.body.map(normPrices).filter(function (l) { return l.length > 2; });
        if (words(body.join(" ")) < 8) return;
        const parts = splitBody(body);
        parts.forEach(function (part, k) {
          pushChunk(p, pageTitle, sec.heading, "primary", part, slug(sec.heading) + (parts.length > 1 ? "-" + (k + 1) : ""));
          pageText += part;
        });
      });
      if (chunks.length === before) { status = "failed"; reason = "no content chunks produced"; }
    }
  }
  report.push({ key: p.key, url: p.url, status: status, reason: reason, chunks: chunks.length - before, words: words(pageText), hash: hash(pageText) });
});

const PROFILE = "https://www.placidway.com/profile/5/Alternative-Cancer-Treatment-by-ITC-Immunity-Therapy-Center";
const statics = [
  { id: "static--contact-and-quote", section: "Contact and free quote", type: "contact", text: "To request a free quote or more information, use the PlacidWay free quote form at https://www.placidway.com/request-info or the ITC-specific quote page at https://www.placidway.com/rfi/5/Alternative-Cancer-Treatment-by-ITC-Immunity-Therapy-Center. Call toll free +1-888-296-6664. Email info@placidway.com." },
  { id: "static--accreditation-note", section: "Accreditation logos on the page", type: "note", text: "The PlacidWay footer banner shows accreditation logos (JCI, ISO, COFEPRIS and others) for organizations PlacidWay collaborates with. This banner is PlacidWay-wide and does not say that ITC holds JCI, ISO or any of these accreditations. The only ITC-specific regulatory statement on the profile page is that the center is approved by COFEPRIS." },
  { id: "static--patient-stories-summary", section: "Patient stories and reviews (summary only)", type: "patient_story_summary", text: "The pages include patient stories, reviews and video titles describing individual patient experiences. These are personal accounts, not clinical data, and this knowledge base does not repeat individual outcomes. The pages do not provide success rates, survival statistics or clinical trial results." }
];
statics.forEach(function (s) {
  chunks.push({ id: s.id, url: PROFILE, title: "ITC Immunity Therapy Center profile", page_type: "profile", section: s.section, chunk_type: s.type, text: "[ITC profile" + ARROW + s.section + "] " + s.text });
});

return [{ json: { scrapedAt: scrapedAt, pages: report, chunks: chunks, failed: report.filter(function (r) { return r.status !== "ok"; }).map(function (r) { return r.key + ": " + r.reason; }) } }];

const NL = String.fromCharCode(10);
const ex = $("Extract and Chunk").first().json;
const listed = $input.first().json;
const files = Array.isArray(listed.files) ? listed.files : [];
const autos = files.filter(function (f) { return f.metadata && f.metadata.kind === "pw-kb-auto"; });
autos.sort(function (a, b) { return String(b.created_on || "").localeCompare(String(a.created_on || "")); });
const prev = autos.length ? autos[0] : null;
const prevHashes = {};
if (prev && Array.isArray(prev.metadata.page_hashes)) {
  prev.metadata.page_hashes.forEach(function (s) { const i = s.indexOf(":"); if (i > 0) prevHashes[s.slice(0, i)] = s.slice(i + 1); });
}
const changed = [];
const unchanged = [];
const added = [];
ex.pages.forEach(function (p) {
  if (p.status !== "ok") return;
  if (!prev || prevHashes[p.key] === undefined) added.push(p.key);
  else if (prevHashes[p.key] !== p.hash) changed.push(p.key);
  else unchanged.push(p.key);
});
const failed = ex.failed;
const safe = failed.length === 0 && ex.chunks.length >= 25;
const stamp = new Date().toISOString();
const header = "# ITC Immunity Therapy Center: Chatbot Knowledge Base (auto-generated)" + NL + NL + "Scraped " + stamp + " from the 7 shared PlacidWay pages only. Each chunk starts with a line beginning with '## [CHUNK]'." + NL + NL;
const blocks = ex.chunks.map(function (c) {
  return "## [CHUNK] " + c.id + NL + "url: " + c.url + NL + "title: " + c.title + NL + "page_type: " + c.page_type + NL + "section: " + c.section + NL + "chunk_type: " + c.chunk_type + NL + "page_date: " + ex.scrapedAt + NL + "page_date_kind: scraped" + NL + NL + c.text;
});
const kbText = header + blocks.join(NL + NL) + NL;
const fileName = "kb-auto-" + stamp.slice(0, 16).split(":").join("").split("-").join("") + ".md";
const meta = { kind: "pw-kb-auto", refreshed_at: stamp, chunk_count: ex.chunks.length, page_hashes: ex.pages.filter(function (p) { return p.status === "ok"; }).map(function (p) { return p.key + ":" + p.hash; }) };
return [{ json: { safe: safe, kbText: kbText, fileName: fileName, metadataJson: JSON.stringify(meta), changed: changed, unchanged: unchanged, added: added, failed: failed, chunkCount: ex.chunks.length, previousFile: prev ? prev.name : null, existingFiles: files.map(function (f) { return f.name + " (" + f.status + ")"; }) } }];

const cfg = $("Config").first().json;
const plan = $("Plan Refresh").first().json;
const up = $("Upload KB File").first().json;
const listed = $input.first().json;
const files = Array.isArray(listed.files) ? listed.files : [];
const newId = up && up.id ? up.id : "";
const mine = files.find(function (f) { return f.id === newId; });
const status = mine ? mine.status : "unknown";
const ready = status === "Available";
const deleteIds = [];
const legacy = [];
files.forEach(function (f) {
  if (f.id === newId) return;
  const kind = f.metadata && f.metadata.kind;
  if (kind === "pw-kb-auto") deleteIds.push(f.id);
  else if (cfg.deleteLegacyFiles === true) deleteIds.push(f.id);
  else legacy.push(f.name);
});
return [{ json: { newFile: (up && up.name) || plan.fileName, newFileId: newId, status: status, ready: ready, replacedFileIds: ready ? deleteIds : [], legacyFilesKept: legacy } }];

const ex = $("Extract and Chunk").first().json;
const plan = $("Plan Refresh").first().json;
const robots = $("Page List and Robots Check").first().json;
let fin = null;
try { fin = $("Finalize").first().json; } catch (e) { fin = null; }
let note = "";
if (!plan.safe) note = "Upload skipped: not every page was extracted cleanly, so the existing knowledge base was left untouched.";
else if (fin && !fin.ready) note = "New file uploaded but still processing; old auto-generated files will be cleaned up on the next refresh.";
else if (fin) note = "Knowledge base refreshed.";
return [{ json: {
  action: fin ? "uploaded" : "skipped",
  note: note,
  refreshedAt: new Date().toISOString(),
  chunkCount: plan.chunkCount,
  pages: ex.pages.map(function (p) { return { key: p.key, status: p.status, reason: p.reason, chunks: p.chunks, words: p.words }; }),
  changedPages: plan.changed,
  newPages: plan.added,
  unchangedPages: plan.unchanged,
  failedPages: plan.failed,
  blockedByRobots: robots.blockedPages,
  robotsTxt: robots.robotsStatus,
  file: fin ? { name: fin.newFile, id: fin.newFileId, status: fin.status } : null,
  legacyFilesKept: fin ? fin.legacyFilesKept : plan.existingFiles,
  replacedFileIds: fin ? fin.replacedFileIds : []
} }];
